p='src/CheckoutPricing.Application/CalculatePayableTotal.cs'
s=open(p).read()
old="""    public int For(string tier, int subtotalCents)
    {
        return subtotalCents;
    }"""
new="""    public int For(string tier, int subtotalCents)
    {
        var baseRate = tier switch
        {
            "Bronze" => 5,
            "Silver" => 7,
            "Gold" => 9,
            _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, "Unknown loyalty tier."),
        };
        var sizeBonus = subtotalCents >= 20000 ? 3 : subtotalCents >= 5000 ? 1 : 0;
        var effectiveRate = Math.Min(baseRate + sizeBonus, 10);
        var discountCents = subtotalCents * effectiveRate / 100;

        return subtotalCents - discountCents;
    }"""
assert old in s
open(p,'w').write(s.replace(old,new))
E
